export const StepDoneIcon = icon(Tick02Icon, "StepDoneIcon")

/* The rail's disclosure chevron. It points down when the section is open and
   is rotated a quarter turn when it is not, so one glyph carries both states
   rather than two glyphs that have to be told apart. */
export const SectionToggleIcon = icon(ArrowDown01Icon, "SectionToggleIcon")

/* The tabs demo. One glyph per view of the same call, each naming what that
   view holds — the bar is the thing being demonstrated, so the labels carry
   an icon the way a real settings or record bar does. */
export const TranscriptIcon = icon(BubbleChatIcon, "TranscriptIcon")
export const ModelIcon = icon(CpuIcon, "ModelIcon")
export const CostIcon = icon(Coins01Icon, "CostIcon")

/* The header control that hands this exact topic to someone. The tick is the
   same glyph a finished step uses — one "done" mark across the reference,
   rather than a second one that has to be learned. */
export const CopyLinkIcon = icon(CopyLinkGlyph, "CopyLinkIcon")
export const CopiedIcon = icon(Tick02Icon, "CopiedIcon")

/* Copies a whole section out as a skill file. */
export const CopySkillIcon = icon(Copy01Icon, "CopySkillIcon")

/* The three states that are not the populated one, each named for the state
   rather than the glyph: nothing here yet, nothing matched, and it broke. */
export const NoResultsIcon = icon(SearchRemoveIcon, "NoResultsIcon")
export const SourceIcon = icon(BookOpen02Icon, "SourceIcon")
export const RetryIcon = icon(RefreshIcon, "RetryIcon")

/* The ring's way back up a level: from one section's topics to the five
   sections themselves. Named for where it goes rather than for the arrow,
   because the same glyph points back to two different places on this page. */
export const AllSectionsIcon = icon(ArrowLeft01Icon, "AllSectionsIcon")

/** The trailing mark on a section row on the overview. */
export const OpenSectionIcon = icon(ArrowRight01Icon, "OpenSectionIcon")

/* One per section on the overview. Named for the shelf, not the glyph, and
   present for the reason the house rules allow an icon in a list at all: five
   cards that differ only by a word are quicker to tell apart with a mark than
   without one. Nothing else on that page carries an icon. */
export const FoundationsIcon = icon(ColorsIcon, "FoundationsIcon")
export const MotionSectionIcon = icon(
  EaseCurveControlPointsIcon,
  "MotionSectionIcon",
)
export const PatternsIcon = icon(DashboardSquare01Icon, "PatternsIcon")
export const CustomComponentsIcon = icon(CubeIcon, "CustomComponentsIcon")
export const ShadcnComponentsIcon = icon(ComponentIcon, "ShadcnComponentsIcon")

/* The Icons tile's subject: one everyday glyph from the set the product draws
   from, set on its construction sheet by the tile's drawing. */
export const IconsTopicGlyph = icon(Home01Icon, "IconsTopicGlyph")

/* The index-page demo's header action. */
export const StartCallIcon = icon(CallOutgoing01Icon, "StartCallIcon")

/* The scenarios index: its two header tiles, the admin scope, and the row's
   one icon action. */
export const CreateScenarioIcon = icon(PlusSignIcon, "CreateScenarioIcon")
export const PlaygroundIcon = icon(Robot01Icon, "PlaygroundIcon")
export const OrganisationIcon = icon(Building02Icon, "OrganisationIcon")
export const CreateTemplateIcon = icon(FileValidationIcon, "CreateTemplateIcon")
